_log = logging.getLogger("transub_engine.asr.qwen3_island")

_VAD_CHUNK_THRESHOLD_S = 0.5


_VAD_MAX_GROUP_S = 5.0


_VAD_MIN_ISLAND_S = 0.22


_VAD_MERGE_GAP_S = 0.5


def _qwen_island_group_params(
    backend: str,
    vad_options: dict[str, Any] | None,
    *,
    demucs_active: bool,
) -> tuple[float, float]:
    """Gap / max span for ``group_vad_intervals`` after VAD collect.

    FireRed already merged at ~0.28s / 5s, so packing with the same gap is a
    no-op. TEN collect has no max-speech cap and a 0.28s merge plus a second
    0.28–0.5s pack glues A/B turns into one Qwen window (mixed speakers,
    painted timestamps). Keep TEN islands as collected; only split mega spans.
    """
    kind = str(backend or "ten").strip().lower()
    if kind == "ten" and not demucs_active:
        max_s = _VAD_MAX_GROUP_S
        if isinstance(vad_options, dict):
            raw = vad_options.get("maxSingleSegmentMs", vad_options.get("max_single_segment_time"))
            try:
                if raw is not None:
                    max_s = max(2.0, min(5.0, float(raw) / 1000.0))
            except (TypeError, ValueError):
                pass
        return 0.15, max_s
    if demucs_active:
        group_gap = 0.55
        group_max = 5.0
        try:
            from ..vad.firered_vad_seg import resolve_firered_params

            frp = resolve_firered_params(vad_options)
            group_max = max(4.0, min(5.5, float(frp["max_speech_s"])))
        except Exception:
            pass
        return group_gap, group_max
    group_gap = _VAD_CHUNK_THRESHOLD_S
    group_max = _VAD_MAX_GROUP_S
    try:
        from ..vad.firered_vad_seg import resolve_firered_params

        frp = resolve_firered_params(vad_options)
        group_gap = max(0.22, min(0.55, float(frp["merge_gap_s"])))
        group_max = max(3.5, min(7.0, float(frp["max_speech_s"])))
    except Exception:
        pass
    return group_gap, group_max


def _qwen_island_vad_transcribe(
    *,
    media_path: str,
    model: Any,
    lang: str | None,
    duration_s: float,
    vad_backend: str = "ten",
    device: str = "auto",
    asr_model: str = "",
    asr_dir: Path | str | None = None,
    aligner_dir: Path | str | None = None,
    qwen_batch_mode: str | None = "auto",
    perf_profile: str | None = None,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
    island_batch_n: int | None = None,
    want_ts: bool = False,
    vad_options: dict[str, Any] | None = None,
    vad_media_path: str | None = None,
    timing_media_path: str | None = None,
    singing_karaoke: bool | None = None,
    on_progress: ProgressCb | None,
    on_cue: CueCb | None,
    should_cancel: Callable[[], bool] | None,
) -> list[dict[str, Any]] | None:
    """TEN or FireRed VAD frames → Qwen text; islands gate ASR windows.

    Cue bounds prefer ForcedAligner stamps (when ``want_ts``) or PCM
    speech-active subspans inside each island — not char-proportional paint
    across the full padded VAD frame.

    ``vad_media_path`` (optional): Demucs vocals for VAD only; ASR PCM still
    comes from ``media_path`` (enhance-for-VAD-only).

    ``timing_media_path`` (optional): pre-Demucs mix when ASR hears vocals
    (full film enhance). Cue paint uses measured mix PCM ends so timestamps
    match playback; recognition still uses Demucs vocals.
    """
    from .speech_spans import group_vad_intervals
    from ..vad.ten_vad_seg import asr_pcm_for_vad_intervals, load_float32_mono_16k

    media_name = Path(media_path).name
    vad_path = str(vad_media_path or "").strip() or media_path
    vad_name = Path(vad_path).name
    timing_path = str(timing_media_path or "").strip()
    backend = str(vad_backend or "ten").strip().lower()
    # Demucs vocals for VAD only (ASR stays on mix). Detect early so TEN merge
    # gap is not shrunk by App minSilenceMs=350 soft-AV shredding.
    demucs_vad_only = vad_path != media_path
    # Full Demucs: ASR media is vocals; timingMedia keeps the mix for paint.
    demucs_asr_on_vocals = bool(timing_path) and timing_path != media_path
    demucs_active = demucs_vad_only or demucs_asr_on_vocals
    intervals: list[tuple[float, float]] | None = None
    audio_f32: Any = None
    timing_f32: Any = None
    label = "TEN"
    max_media = duration_s if duration_s > 0 else None
    clock = StageClock(f"Qwen-{Path(media_path).stem}")
    # Overlap mix/timing decode with vocals VAD (enhanceForVadOnly / full Demucs).
    preload_pool: ThreadPoolExecutor | None = None
    mix_future: Future[Any] | None = None
    timing_future: Future[Any] | None = None
    try:
        if demucs_vad_only:
            preload_pool = ThreadPoolExecutor(max_workers=1)
            mix_future = preload_pool.submit(
                load_float32_mono_16k, media_path, max_media_s=max_media
            )
        elif demucs_asr_on_vocals:
            preload_pool = ThreadPoolExecutor(max_workers=1)
            timing_future = preload_pool.submit(
                load_float32_mono_16k, timing_path, max_media_s=max_media
            )

        if backend == "firered":
            label = "FireRed"
            try:
                from ..runtime_extras import ensure_extras_for_models
                from ..vad.firered_vad_seg import (
                    collect_firered_vad_intervals_with_audio,
                    firered_vad_available,
                    firered_weights_dir,
                )

                ensure_extras_for_models(
                    ["firered-vad"], force=False, on_progress=on_progress
                )
                if not firered_vad_available() or firered_weights_dir() is None:
                    _log.info(
                        "Qwen FireRed path skipped: package/weights missing | %s -> TEN/windowed",
                        vad_name,
                    )
                    backend = "ten"
                else:
                    # Demucs vocals: keep merge gap short so max_speech cap holds.
                    fr_gap = 0.28 if demucs_active else _VAD_MERGE_GAP_S
                    intervals, audio_f32 = collect_firered_vad_intervals_with_audio(
                        vad_path,
                        max_media_s=max_media,
                        merge_gap_s=fr_gap,
                        max_speech_s=5.0 if demucs_active else None,
                        vad_options=vad_options,
                        device=device,
                    )
                    clock.log_mark(
                        "vad_firered",
                        media=vad_name,
                        islands=len(intervals or []),
                    )
                    try:
                        from ..vad.firered_vad_seg import clear_firered_vad_cache

                        clear_firered_vad_cache()
                    except Exception:
                        pass
            except Exception as err:
                _log.warning(
                    "Qwen FireRed VAD collect failed for %s: %s -> TEN/windowed",
                    vad_name,
                    err,
                )
                backend = "ten"
                intervals = None
                audio_f32 = None

        if backend == "ten":
            label = "TEN"
            from ..vad.ten_vad_seg import (
                collect_ten_vad_intervals_with_audio,
                resolve_ten_params,
                ten_vad_available,
            )

            if not ten_vad_available():
                _log.info(
                    "Qwen TEN path skipped: ten-vad not installed | %s -> windowed fallback",
                    vad_name,
                )
                return None
            try:
                tp = resolve_ten_params(vad_options)
                # Prefer island default merge gap when soft-AV silence knob unset.
                merge_gap = float(tp["merge_gap_s"])
                threshold = float(tp["threshold"])
                min_speech_s = float(tp["min_speech_s"])
                pad_s = float(tp["pad_s"])
                if (
                    not isinstance(vad_options, dict)
                    or (
                        vad_options.get("minSilenceMs") is None
                        and vad_options.get("min_silence_duration_ms") is None
                    )
                ):
                    merge_gap = _VAD_MERGE_GAP_S
                # Demucs→VAD-only: App soft-AV UI often sends threshold=0.3 +
                # minSilenceMs=350 + speechPadMs=120. Hot threshold/short merge keep
                # TEN open across breaths (30s+ mega islands); silence-split then
                # bisects turns (DLDSS-559: テレビ@5.58 / 作ってみた@8.25). Extra pad
                # paints cue starts into leading silence (SILENT_START). Floor to
                # TEN defaults used by the good (no-vad_options) path.
                if demucs_active:
                    _ten_default = resolve_ten_params(None)
                    merge_gap = max(float(merge_gap), float(_VAD_MERGE_GAP_S))
                    threshold = max(float(threshold), float(_ten_default["threshold"]))
                    min_speech_s = max(
                        float(min_speech_s), float(_ten_default["min_speech_s"])
                    )
                    pad_s = min(float(pad_s), float(_ten_default["pad_s"]))
                else:
                    # Soft-AV TEN: UI minSilence 280ms + pad 120ms otherwise
                    # welds A/B turns into one ASR island.
                    merge_gap = min(float(merge_gap), 0.18)
                    pad_s = min(float(pad_s), 0.10)
                intervals, audio_f32 = collect_ten_vad_intervals_with_audio(
                    vad_path,
                    max_media_s=max_media,
                    threshold=threshold,
                    min_speech_s=min_speech_s,
                    merge_gap_s=merge_gap,
                    pad_s=pad_s,
                )
                clock.log_mark(
                    "vad_ten",
                    media=vad_name,
                    islands=len(intervals or []),
                )
            except Exception as err:
                _log.warning(
                    "Qwen TEN VAD collect failed for %s: %s -> windowed fallback",
                    vad_name,
                    err,
                )
                return None

        if not intervals:
            _log.info(
                "Qwen %s VAD found no speech on %s; windowed fallback",
                label,
                vad_name,
            )
            return None

        preloaded_mix = None
        if mix_future is not None:
            try:
                preloaded_mix = mix_future.result()
                clock.log_mark("mix_pcm_parallel", samples=getattr(preloaded_mix, "size", None))
            except Exception as err:
                _log.warning("parallel mix PCM decode failed: %s", err)
                preloaded_mix = None

        audio_f32 = asr_pcm_for_vad_intervals(
            media_path,
            vad_media_path=vad_path if vad_path != media_path else None,
            vad_pcm=audio_f32,
            max_media_s=max_media,
            asr_pcm=preloaded_mix,
        )
        if demucs_vad_only and preloaded_mix is None:
            clock.log_mark("mix_pcm_serial")

        # Demucs vocals: re-split only true leftovers (>12s). FireRed merge now
        # respects max_speech so refine is usually a cheap no-op.
        if demucs_active and intervals:
            try:
                from .whisper_fw import refine_demucs_vad_intervals

                before_n = len(intervals)
                intervals = refine_demucs_vad_intervals(
                    intervals,
                    audio_f32,
                    _QWEN_SR,
                    long_island_s=12.0,
                    min_silence_s=0.48,
                )
                clock.log_mark(
                    "demucs_refine",
                    before=before_n,
                    after=len(intervals),
                )
                if len(intervals) != before_n and on_progress:
                    on_progress(
                        {
                            "stage": "vad",
                            "percent": 13,
                            "detail": (
                                f"{label} Demucs 长岛重切 {before_n}→{len(intervals)}"
                                f"（按{'原音' if demucs_vad_only else '人声'}停顿）"
                            ),
                        }
                    )
            except Exception as err:
                _log.debug("Demucs island refine skipped: %s", err)

        # Full Demucs: mix PCM for cue paint (prefer parallel preload).
        if demucs_asr_on_vocals:
            try:
                if timing_future is not None:
                    timing_f32 = timing_future.result()
                else:
                    timing_f32 = load_float32_mono_16k(
                        timing_path, max_media_s=max_media
                    )
                clock.log_mark(
                    "timing_pcm",
                    media=Path(timing_path).name,
                )
                _log.info(
                    "Qwen %s timing PCM: mix=%s | ASR vocals=%s | preserve_acoustic_ends=1",
                    label,
                    Path(timing_path).name,
                    media_name,
                )
            except Exception as err:
                _log.warning(
                    "Qwen %s timing mix load failed (%s); paint falls back to ASR PCM",
                    label,
                    err,
                )
                timing_f32 = None
        elif demucs_vad_only:
            _log.info(
                "Qwen %s timing PCM: ASR mix=%s | VAD vocals=%s | preserve_acoustic_ends=1",
                label,
                media_name,
                vad_name,
            )
    finally:
        if preload_pool is not None:
            preload_pool.shutdown(wait=False)

    # Same sparse policy as WhisperSeg for *empty* VAD. Large holes alone used
    # to discard all islands → full 90s windows; on soft AV Qwen often returns
    # only "…" and drops intro dialogue TEN already found (NAAC-076). Hybrid:
    # keep islands + fill ≥90s gaps.
    hole_fill_windows: list[tuple[float, float]] = []
    try:
        from ..vad.whisperseg import classify_vad_coverage

        cov_clips = [
            {"start": float(s), "end": float(e)}
            for s, e in intervals
            if float(e) > float(s)
        ]
        coverage = classify_vad_coverage(cov_clips, duration_s=duration_s)
        if coverage == "empty":
            spoken = sum(max(0.0, c["end"] - c["start"]) for c in cov_clips)
            ratio = (spoken / duration_s) if duration_s > 0 else 0.0
            _log.info(
                "Qwen %s VAD too sparse on %s (islands=%d spoken=%.1f%%) -> windowed fallback",
                label,
                media_name,
                len(cov_clips),
                ratio * 100.0,
            )
            if on_progress:
                on_progress(
                    {
                        "stage": "vad_failover",
                        "percent": 14,
                        "detail": (
                            f"{label} 过稀（人声约 {ratio:.1%}）· 回退定长开窗"
                            if cov_clips
                            else f"{label} 无岛 · 回退定长开窗"
                        ),
                    }
                )
            return None
        if coverage == "holes":
            hole_fill_windows = _vad_hole_fill_windows(
                cov_clips, duration_s=duration_s, min_hole_s=90.0
            )
            spoken = sum(max(0.0, c["end"] - c["start"]) for c in cov_clips)
            ratio = (spoken / duration_s) if duration_s > 0 else 0.0
            _log.info(
                "Qwen %s hybrid on %s: keep islands=%d spoken=%.1f%% + hole_windows=%d",
                label,
                media_name,
                len(cov_clips),
                ratio * 100.0,
                len(hole_fill_windows),
            )
            if on_progress:
                on_progress(
                    {
                        "stage": "vad",
                        "percent": 14,
                        "detail": (
                            f"{label} 岛保留 + 空洞补窗 "
                            f"{len(hole_fill_windows)}（人声约 {ratio:.1%}）"
                        ),
                    }
                )
    except Exception as err:
        _log.warning("Qwen %s sparse coverage check failed: %s", label, err)

    group_gap, group_max = _qwen_island_group_params(
        backend,
        vad_options,
        demucs_active=demucs_active,
    )
    pieces = group_vad_intervals(
        intervals,
        chunk_threshold_s=group_gap,
        max_group_duration_s=group_max,
    )
    if not pieces and not hole_fill_windows:
        return None

    # Lazy spans: keep only (start, end). Materialize PCM per batch so multi-hour
    # jobs do not hold thousands of island .copy() buffers (~hundreds of MiB).
    frames: list[tuple[float, float]] = []
    for start, end in pieces:
        if max(0.0, end - start) < _VAD_MIN_ISLAND_S:
            continue
        frames.append((float(start), float(end)))
    for start, end in hole_fill_windows:
        if max(0.0, end - start) < _VAD_MIN_ISLAND_S:
            continue
        frames.append((float(start), float(end)))
    if not frames:
        return None

    batch_n = max(
        1,
        int(island_batch_n)
        if island_batch_n is not None and int(island_batch_n) > 0
        else resolve_island_batch_size(
            asr_model,
            batch_mode=qwen_batch_mode,
            device=device,
            perf_profile=perf_profile,
            job_gpu_free_mib=job_gpu_free_mib,
            job_gpu_total_mib=job_gpu_total_mib,
        ),
    )
    effective_mode = _effective_batch_mode(qwen_batch_mode, perf_profile)
    batch_label = effective_mode
    _set_island_batch_ctx(
        asr_model=asr_model,
        device=device,
        batch_mode=effective_mode,
    )
    pcm_n = len(frames) if audio_f32 is not None else 0
    clock.log_mark(
        "frame_build",
        frames=len(frames),
        batch=batch_n,
        mode=batch_label,
        lazy_pcm=1 if audio_f32 is not None else 0,
        group_gap=round(group_gap, 2),
        group_max=round(group_max, 2),
    )
    _log.info(
        "Qwen %s frames: %s | islands=%d -> frames=%d | lazy_pcm=%d/%d | batch=%d (%s) | first=%.1f-%.1fs",
        label,
        media_name,
        len(intervals),
        len(frames),
        pcm_n,
        len(frames),
        batch_n,
        batch_label,
        frames[0][0],
        frames[0][1],
    )

    work: Path | None = None
    all_cues: list[dict[str, Any]] = []
    fail_count = 0
    ffmpeg_n = 0
    solo_retry_n = 0
    half_retry_n = 0
    first_err: BaseException | None = None
    last_key = ""
    same_streak = 0
    active_model = model
    cpu_fallback_done = False
    asr_t0 = time.perf_counter()
    try:
        if on_progress:
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": 12,
                    "detail": f"{label} 人声帧 {len(frames)} 段 · 批 {batch_n} ({batch_label}) | Qwen3-ASR",
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )
        idx = 0
        while idx < len(frames):
            raise_if_island_cancelled(should_cancel)
            oom_cap = get_island_batch_oom_cap(asr_model, device, effective_mode)
            cur_batch = batch_n
            if oom_cap is not None:
                cur_batch = min(cur_batch, max(1, int(oom_cap)))
            # After ROCm→CPU remount, keep batch tiny.
            if cpu_fallback_done:
                cur_batch = 1
            cur_batch = limit_island_batch_homogeneous(frames, idx, cur_batch)
            chunk = frames[idx : idx + cur_batch]
            audios: list[Any] = []
            # Parallel PCM/path handles for solo/leftover retry (released after batch).
            items: list[Any] = []
            for j, (start, end) in enumerate(chunk):
                item = (
                    _pcm_tuple_for_span(audio_f32, start, end)
                    if audio_f32 is not None
                    else None
                )
                if item is not None:
                    audios.append(item)
                    items.append(item)
                    continue
                from ..audio.preprocess import trim_media_window

                if work is None:
                    work = make_island_workdir("qwen3_vad_")
                wav = trim_media_window(
                    media_path,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"f{idx + j:04d}",
                )
                audios.append(str(wav))
                items.append(str(wav))
                ffmpeg_n += 1
            start0 = float(chunk[0][0])
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start0,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": (
                            f"{label} {idx + 1}–{idx + len(chunk)}/{len(frames)}"
                            f" · {format_mmss(start0)}"
                            + (" · CPU回退" if cpu_fallback_done else "")
                        ),
                        "processedSec": start0,
                        "mediaDurationSec": duration_s,
                    }
                )
            try:
                results = _transcribe_audio_list(
                    active_model,
                    audios,
                    lang,
                    want_ts=want_ts,
                    max_new_tokens=(
                        None if want_ts else _ISLAND_MAX_NEW_TOKENS
                    ),
                )
            except Exception as err:
                if is_hip_invalid_value(err) or _is_cuda_oom(err):
                    _empty_cuda_cache()
                # ROCm RDNA4: if float32 single-frame still HIP-invalid, remount on CPU once.
                if (
                    not cpu_fallback_done
                    and _torch_is_rocm()
                    and is_hip_invalid_value(err)
                    and len(chunk) <= 1
                    and asr_dir is not None
                    and str(getattr(active_model, "device", "") or "").startswith("cuda")
                ):
                    _log.warning(
                        "Qwen %s ROCm HIP invalid on single frame; "
                        "remounting model on CPU for remaining frames: %s",
                        label,
                        err,
                    )
                    try:
                        clear_hf_model_cache()
                        active_model = load_qwen3_hf_bundle(
                            Path(asr_dir),
                            device="cpu",
                            aligner_dir=Path(aligner_dir) if aligner_dir else None,
                        )
                        cpu_fallback_done = True
                        if on_progress:
                            on_progress(
                                {
                                    "stage": "transcribe",
                                    "percent": int(
                                        asr_local_from_timeline(
                                            processed_s=start0,
                                            duration_s=duration_s,
                                            start=12.0,
                                            end=92.0,
                                        )
                                    ),
                                    "detail": (
                                        f"{label} ROCm 内核失败 → 改用 CPU 继续"
                                        f"（较慢）· {format_mmss(start0)}"
                                    ),
                                    "processedSec": start0,
                                    "mediaDurationSec": duration_s,
                                }
                            )
                        # Retry the same chunk on CPU without advancing idx.
                        continue
                    except Exception as remount_err:
                        _log.warning(
                            "Qwen %s CPU remount after HIP failed: %s",
                            label,
                            remount_err,
                        )
                fail_count += len(chunk)
                if first_err is None:
                    first_err = err
                key = str(err)[:240]
                same_streak = same_streak + 1 if key == last_key else 1
                last_key = key
                _log.warning(
                    "Qwen %s batch %d–%d failed: %s",
                    label,
                    idx + 1,
                    idx + len(chunk),
                    err,
                )
                if _qwen_fail_fast(err=err, first_err=first_err, same_streak=same_streak):
                    raise RuntimeError(
                        f"Qwen3-ASR {label} failed {fail_count}/{len(frames)} frames "
                        f"({media_name}): {_qwen_error_text(first_err)}"
                    ) from err
                idx += len(chunk)
                continue
            note_island_batch_success(
                asr_model,
                device,
                effective_mode,
                target_batch=batch_n,
                used_batch=len(chunk),
            )
            singing = _yue_want_singing_post(
                lang, vad_options, singing_karaoke=singing_karaoke
            )
            for (start, end), item, result in zip(chunk, items, results):
                span = max(0.1, float(end) - float(start))
                # Prefer mix PCM spans when Demucs ASR hears vocals so cue ends
                # track playback (preserve_acoustic_ends in _distribute_text_cues).
                span_item = item
                if timing_f32 is not None:
                    span_item = _pcm_tuple_for_span(
                        timing_f32, float(start), float(end)
                    )
                speech_spans = _speech_spans_from_frame_pcm(
                    span_item, island_start=float(start)
                )
                span_n = len(speech_spans or [])
                # Weak always; truncated/filler on spoken dialogue — skip moan SFX.
                if _should_solo_retry_island(
                    _result_text(result),
                    span_s=span,
                    speech_span_n=span_n,
                ):
                    result, retry_kind = _solo_retry_weak_island_result(
                        active_model=active_model,
                        item=item,
                        result=result,
                        lang=lang,
                        want_ts=want_ts,
                        start=float(start),
                        end=float(end),
                        label=label,
                        speech_span_n=span_n,
                    )
                    if retry_kind == "solo":
                        solo_retry_n += 1
                    elif retry_kind == "half":
                        half_retry_n += 1
                if want_ts:
                    part = _result_to_cues_aligned(
                        result,
                        offset_s=float(start),
                        span_s=span,
                        speech_spans=speech_spans,
                        singing=singing,
                    )
                else:
                    text = _result_text(result)
                    if not text:
                        continue
                    part = _distribute_text_cues(
                        text,
                        start=start,
                        end=end,
                        speech_spans=speech_spans,
                    )
                if (
                    part
                    and item is not None
                    and speech_spans
                    and _island_looks_like_spoken_dialogue(_result_text(result))
                ):
                    covered_s = sum(
                        max(0.0, float(c.get("end") or 0) - float(c.get("start") or 0))
                        for c in part
                    )
                    need_leftover = (
                        _island_transcript_looks_truncated(
                            _result_text(result),
                            span_s=span,
                            speech_span_n=span_n,
                        )
                        or _ends_with_hesitation_filler(_result_text(result))
                        or (span >= 1.6 and covered_s / span < 0.5)
                    )
                    extra = (
                        _retry_uncovered_speech_spans(
                            active_model=active_model,
                            item=item,
                            lang=lang,
                            want_ts=want_ts,
                            island_start=float(start),
                            cues=part,
                            speech_spans=speech_spans,
                            label=label,
                        )
                        if need_leftover
                        else []
                    )
                    if extra:
                        solo_retry_n += 1
                        part = _sort_cues_by_start([*part, *extra])
                for cue in part:
                    if on_cue:
                        on_cue(cue)
                    all_cues.append(cue)
            # Drop this batch's PCM copies before building the next.
            del audios, items
            idx += len(chunk)
    finally:
        cleanup_island_workdir(work)

    clock.log_mark(
        "asr_infer",
        frames=len(frames),
        solo_retry=solo_retry_n,
        wall_s=round(time.perf_counter() - asr_t0, 2),
    )
    clock.log_summary()
    _log.info(
        "Qwen %s retry stats: %s | frames=%d | solo_retry=%d | half_retry=%d",
        label,
        media_name,
        len(frames),
        solo_retry_n,
        half_retry_n,
    )
    if ffmpeg_n:
        _log.info(
            "Qwen %s used ffmpeg trim for %d/%d frames on %s",
            label,
            ffmpeg_n,
            len(frames),
            media_name,
        )
    if fail_count and not all_cues:
        # Inference itself failed — 90s window fallback would hit the same error.
        raise RuntimeError(
            f"Qwen3-ASR {label} failed {fail_count}/{len(frames)} frames "
            f"({media_name}): {_qwen_error_text(first_err)}"
        )
    if not all_cues:
        return None
    try:
        from .ten_pcm_pack import apply_ten_pcm_timing, resolve_asr_timing_mode
        from .whisper_fw import (
            ensure_readable_cue_timings,
            nudge_cue_starts_past_silence,
            stretch_cues_for_singing,
        )

        media_end = float(duration_s) if duration_s else None
        # Cantonese song/MV (FireRed ± ForcedAligner): skip spoken-rate
        # ensure_readable (CPS~9) — it rewrites island gaps and blocks XLSub-sized
        # merge. Merge short islands/aligner fragments, then singing-rate stretch.
        if _yue_want_singing_post(lang, vad_options, singing_karaoke=singing_karaoke):
            from .whisper_fw import merge_cues_for_singing

            # ForcedAligner singing already packs words into XLSub-sized lines;
            # re-merging across islands glues choruses (躯壳+光辉+风雨…).
            if not want_ts:
                all_cues = merge_cues_for_singing(all_cues)
            all_cues = stretch_cues_for_singing(
                all_cues, media_end_s=media_end, drop_fillers=True
            )
        else:
            timing_mode = resolve_asr_timing_mode(vad_options)
            polish_pcm = timing_f32 if timing_f32 is not None else audio_f32
            if timing_mode == "ten_pcm" and polish_pcm is not None:
                # Pro-style timing authority: TEN islands + PCM subspans + polish.
                # Text/order stay from Qwen; absolute bounds are recomputed.
                island_spans = [(float(a), float(b)) for a, b in frames]
                try:
                    all_cues, ten_detail = apply_ten_pcm_timing(
                        all_cues,
                        audio_f32=polish_pcm,
                        sample_rate=_QWEN_SR,
                        islands=island_spans,
                        media_end_s=media_end,
                        # ForcedAligner already owns acoustic starts/ends —
                        # only run polish, do not re-slot by char weight.
                        reallocate=not bool(want_ts),
                    )
                    _log.info("Qwen ten_pcm applied (%s)", ten_detail)
                except Exception as err:
                    _log.warning("Qwen ten_pcm failed; falling back: %s", err)
                    try:
                        all_cues = nudge_cue_starts_past_silence(
                            all_cues, polish_pcm, sample_rate=_QWEN_SR
                        )
                    except Exception:
                        pass
                    all_cues = ensure_readable_cue_timings(
                        all_cues,
                        media_end_s=media_end,
                        stretch_to_reading_rate=False,
                    )
            else:
                if audio_f32 is not None:
                    try:
                        all_cues = nudge_cue_starts_past_silence(
                            all_cues, audio_f32, sample_rate=_QWEN_SR
                        )
                    except Exception:
                        pass
                # TEN/FireRed PCM paint and ForcedAligner both own acoustic bounds.
                # Reading-rate stretch/clamp soft_cap shortens cues vs spoken audio.
                all_cues = ensure_readable_cue_timings(
                    all_cues,
                    media_end_s=media_end,
                    stretch_to_reading_rate=False,
                )
    except Exception:
        pass
    return _dedupe_overlap_cues(all_cues)
